      "path": "scripts/mine-transcripts.mjs",
      "content": "#!/usr/bin/env node\n/**\n * dsh-receipts — scripts/mine-transcripts.mjs\n *\n * 从 DSH 本地会话 JSONL 日志挖取「使用与影响报告」摘要（纯本地，零网络）。\n * 移植上游 receipts 的思路（流程与参数语义，实现自写）：\n *   本机会话根目录（默认 `$DSH_HOME/sessions`，按项目/会话两层子目录）里的\n *   `session.jsonl[.zstd]` 日志 → 正则 + JSON 解析 → 摘要 JSON。\n *\n * 网络白名单（验收标准 4）：本文件不得导入任何网络相关核心模块\n * （http / https / net / dns / dgram 等），不得调用 fetch；唯一的子进程调用是\n * 本地 `git`（交叉验证）与可选 `zstd` CLI 回退解码，二者均只访问本机。\n *\n * 两种读取模式（README 说明）：\n *   - `compression: 'none'` 日志：逐行 JSON（plaintext UTF-8）。\n *   - 默认 Zstd 压缩：优先 Node 内建 `node:zlib` 的 Zstd 解码（Node >= 23.4，\n *     实测环境 Node 26 自带）；内建不可用时回退 `zstd -dc` CLI；两者皆无则跳过\n *     该文件并记录原因（不中断）。\n *\n * 用法（CLI）：\n *   node scripts/mine-transcripts.mjs --root <sessionsRoot> [--period week|month|quarter|year|<天数>]\n *       [--repo <项目名子串>] [--now <epoch-ms>] [--summary-out <path>]\n *       [--redact] [--no-git] [--git-bin git] [--cap-bytes <n>]\n *   摘要 JSON 打印到 stdout（--summary-out 时同时写文件）。\n *\n * 库用法（测试直接导入）：\n *   import { mineSessions, parsePeriod } from '../scripts/mine-transcripts.mjs'\n */\n\nimport { execFile as execFileCb } from 'node:child_process'\nimport { promises as fsp } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { basename, dirname, join } from 'node:path'\nimport { fileURLToPath, pathToFileURL } from 'node:url'\nimport { promisify } from 'node:util'\nimport * as zlibMod from 'node:zlib'\n\nconst execFile = promisify(execFileCb)\n\n/** 周期 → 天数表（对齐上游参数语义）。 */\nexport const PERIOD_DAYS = Object.freeze({\n  week: 7,\n  month: 30,\n  quarter: 90,\n  year: 365,\n})\n\nexport const DEFAULT_PERIOD = 'month'\nexport const DEFAULT_PERIOD_DAYS = PERIOD_DAYS[DEFAULT_PERIOD]\n\n/** 摘要上限：20KB（对齐上游「摘要 ≤ 20KB，超出先截断再写」）。 */\nexport const SUMMARY_BYTES_CAP = 20 * 1024\n\n/** 本插件识别的会话日志文件名（其它文件一律忽略）。 */\nexport const LOG_FILE_NAMES = Object.freeze(['session.jsonl', 'session.jsonl.zstd'])\nexport const ZSTD_SUFFIX = '.jsonl.zstd'\n\nexport const DSH_HOME_ENV = 'DSH_HOME'\nexport const DSH_HOME_DIR_NAME = '.dsh'\nexport const SESSIONS_DIR_NAME = 'sessions'\n\nexport const DAY_MS = 86_400_000\nconst HOUR_MS = 3_600_000\nconst MINUTE_MS = 60_000\n\n// ---------------------------------------------------------------------------\n// 路径与周期解析\n// ---------------------------------------------------------------------------\n\n/**\n * 解析 dshHome：`$DSH_HOME` 优先，回退 `~/.dsh`（与 dsh-home-paths 语义一致）。\n * @param env - 环境对象（测试可注入）。\n */\nexport function resolveDshHome(env = process.env) {\n  const override = env[DSH_HOME_ENV]\n  if (typeof override === 'string' && override.trim().length > 0) return override.trim()\n  return join(homedir(), DSH_HOME_DIR_NAME)\n}\n\n/**\n * 解析会话日志根目录：显式 root 优先；否则 `<dshHome>/sessions`。\n * @param opts - `{ sessionsRoot?, dshHome? }`。\n */\nexport function resolveSessionsRoot(opts = {}, env = process.env) {\n  if (opts.sessionsRoot) return opts.sessionsRoot\n  const home = opts.dshHome ?? resolveDshHome(env)\n  return join(home, SESSIONS_DIR_NAME)\n}\n\n/**\n * 解析周期参数：`week`=7 / `month`=30 / `quarter`=90 / `year`=365 / 裸数字=天数。\n * @param period - 周期表示；默认 month。\n * @param now - 基准时间（epoch ms），测试可固定。\n * @returns `{ key, days, since }`。\n */\nexport function parsePeriod(period = DEFAULT_PERIOD, now = Date.now()) {\n  if (typeof period === 'number' && Number.isFinite(period) && period > 0) {\n    const days = Math.floor(period)\n    return { key: `${days}days`, days, since: now - days * DAY_MS }\n  }\n  const raw = String(period).trim().toLowerCase()\n  if (Object.prototype.hasOwnProperty.call(PERIOD_DAYS, raw)) {\n    const days = PERIOD_DAYS[raw]\n    return { key: raw, days, since: now - days * DAY_MS }\n  }\n  const numeric = Number(raw)\n  if (Number.isFinite(numeric) && numeric > 0 && raw !== '') {\n    const days = Math.floor(numeric)\n    return { key: `${days}days`, days, since: now - days * DAY_MS }\n  }\n  throw new Error(`无效周期 \"${period}\"：支持 week|month|quarter|year 或正整数天数`)\n}\n\n// ---------------------------------------------------------------------------\n// 日志发现与解码\n// ---------------------------------------------------------------------------\n\n/** 用 Node 内建 zlib 的 Zstd 解码（Node >= 23.4）；不可用时返回 null。 */\nfunction zstdDecodeBuiltIn(buffer) {\n  const decode = zlibMod.zstdDecompressSync\n  if (typeof decode !== 'function') return null\n  try {\n    return decode(buffer).toString('utf8')\n  } catch {\n    return null\n  }\n}\n\n/** Zstd 帧魔数（RFC 8878，小端 0xFD2FB528）。 */\nconst ZSTD_MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd])\n\n/**\n * 解析从 start 开始的一个 Zstd 帧，返回帧结束偏移（不含下一帧）；无法解析时返回 -1。\n * DSH 会话日志是「多帧拼接」（每 append 批一帧，见 session-persistence-jsonl 文档），\n * Node 内建 zstdDecompressSync 只解第一帧，因此必须按帧边界逐帧解码。\n *\n * 块头位布局以 DSH 自身扫描器（packages/session/session-persistence-jsonl/src/zstd.ts）\n * 为准：3 字节小端整数内 bit0 = Last_Block、bits1-2 = Block_Type、bits3-23 = Block_Size。\n */\nexport function zstdScanFrameEnd(buffer, start) {\n  const len = buffer.length\n  if (start + 5 > len) return -1\n  if (!buffer.subarray(start, start + 4).equals(ZSTD_MAGIC)) return -1\n  const descriptor = buffer[start + 4]\n  if ((descriptor & 0x18) !== 0) return -1 // 保留位被置位\n  const contentSizeFlag = descriptor >>> 6\n  const singleSegment = (descriptor & 0x20) !== 0\n  const checksum = (descriptor & 0x04) !== 0\n  const dictionaryFlag = descriptor & 0x03\n  const dictionaryBytes = dictionaryFlag === 3 ? 4 : dictionaryFlag\n  const contentSizeBytes = contentSizeFlag === 0 ? (singleSegment ? 1 : 0) : 1 << contentSizeFlag\n  // 帧头 = magic(4) + 描述符(1) + Window_Descriptor(1，仅非 Single_Segment) + FCS + DID\n  const headerLen = 5 + (singleSegment ? 0 : 1) + contentSizeBytes + dictionaryBytes\n  let cursor = start + headerLen\n  if (cursor > len) return -1\n  for (;;) {\n    if (cursor + 3 > len) return -1\n    const blockHeader = buffer.readUIntLE(cursor, 3)\n    cursor += 3\n    const lastBlock = (blockHeader & 1) !== 0\n    const blockType = (blockHeader >>> 1) & 0x03\n    const blockSize = blockHeader >>> 3\n    if (blockType === 0x03) return -1\n    const payloadBytes = blockType === 0x01 ? 1 : blockSize // RLE 块只有 1 字节\n    if (cursor + payloadBytes > len) return -1\n    cursor += payloadBytes\n    if (lastBlock) break\n  }\n  if (checksum) cursor += 4\n  return cursor\n}\n\n/**\n * 返回 buffer 中全部 Zstd 帧的 [start, end) 区间（拼接帧场景）。\n */\nexport function zstdFrameRanges(buffer) {\n  const ranges = []\n  let pos = 0\n  while (pos + 4 <= buffer.length) {\n    const start = buffer.indexOf(ZSTD_MAGIC, pos)\n    if (start === -1) break\n    const end = zstdScanFrameEnd(buffer, start)\n    if (end === -1 || end <= start) break\n    ranges.push({ start, end })\n    pos = end\n  }\n  return ranges\n}\n\n/** 单帧压缩数据上限（帧大小护栏）：超过时按解码失败处理，防止超大单帧打爆内存。 */\nexport const ZSTD_MAX_FRAME_BYTES = 64 * 1024 * 1024\n\n/**\n * 逐帧解码拼接的 Zstd 数据成 UTF-8 文本；任一一帧失败返回 null。\n * 无完整帧时回退为整块单帧尝试（兼容普通单帧文件）。\n * 单帧压缩数据长度超过 ZSTD_MAX_FRAME_BYTES（64MB）时同样返回 null（护栏）。\n */\nexport function zstdDecodeAll(buffer) {\n  const ranges = zstdFrameRanges(buffer)\n  if (ranges.length === 0) {\n    if (buffer.length > ZSTD_MAX_FRAME_BYTES) return null\n    return zstdDecodeBuiltIn(buffer)\n  }\n  let out = ''\n  for (const { start, end } of ranges) {\n    if (end - start > ZSTD_MAX_FRAME_BYTES) return null\n    const decoded = zstdDecodeBuiltIn(buffer.subarray(start, end))\n    if (decoded === null) return null\n    out += decoded\n  }\n  return out\n}\n\n/** 用 `zstd -dc` CLI 回退解码；不可用时返回 null。 */\nasync function zstdDecodeCli(absPath, gitBinStyle) {\n  try {\n    const { stdout } = await execFile(gitBinStyle ?? 'zstd', ['-dc', absPath], {\n      timeout: 30_000,\n      maxBuffer: 128 * 1024 * 1024,\n    })\n    return String(stdout)\n  } catch {\n    return null\n  }\n}\n\n/**\n * 解码一个日志文件为 UTF-8 文本。\n * @param absPath - 绝对路径。\n * @param opts - `{ fsImpl?, zstdCli? }`。\n * @returns `{ text }` 或 `{ error }`。\n */\nexport async function decodeLogFile(absPath, opts = {}) {\n  const fsImpl = opts.fsImpl ?? fsp\n  let raw\n  try {\n    raw = await fsImpl.readFile(absPath)\n  } catch (error) {\n    return { error: `读取失败: ${error.message}` }\n  }\n  if (!absPath.endsWith(ZSTD_SUFFIX)) {\n    return { text: Buffer.from(raw).toString('utf8') }\n  }\n  const multiFrame = zstdDecodeAll(Buffer.from(raw))\n  if (multiFrame !== null) return { text: multiFrame }\n  const cli = await zstdDecodeCli(absPath, opts.zstdCli)\n  if (cli !== null) return { text: cli }\n  return {\n    error:\n      `Zstd 解码失败（Node 内建 zlib 与 zstd CLI 均无法解码该文件）。`\n      + `请在 DSH 会话持久化配置中设置 compression: 'none'，`\n      + `或安装 zstd 命令行工具后重试`,\n  }\n}\n\n/**\n * 递归发现 `sessionsRoot` 下的会话日志文件。不跟随符号链接。\n * @returns 绝对路径数组（稳定排序）。\n */\nexport async function discoverLogs(root, fsImpl = fsp, maxDepth = 8) {\n  const found = []\n  const walk = async (dir, depth) => {\n    if (depth > maxDepth) return\n    let entries\n    try {\n      entries = await fsImpl.readdir(dir, { withFileTypes: true })\n    } catch {\n      return\n    }\n    for (const entry of entries) {\n      if (entry.name === '.git' || entry.name === 'node_modules') continue\n      const abs = join(dir, entry.name)\n      if (entry.isDirectory()) {\n        await walk(abs, depth + 1)\n      } else if (entry.isFile() && LOG_FILE_NAMES.includes(entry.name)) {\n        found.push(abs)\n      }\n    }\n  }\n  await walk(root, 0)\n  return [...new Set(found)].sort()\n}\n\n// ---------------------------------------------------------------------------\n// 解析与单会话摘要\n// ---------------------------------------------------------------------------\n\n/** 兼容 ms 数字与 ISO 字符串两种时间编码。 */\nexport function toMs(value) {\n  if (typeof value === 'number' && Number.isFinite(value)) return value\n  if (typeof value === 'string') {\n    const t = Date.parse(value)\n    if (Number.isFinite(t)) return t\n  }\n  return undefined\n}\n\n/**\n * 解析一份 JSONL 文本 → `{ header, events, parseErrors }`。\n * 头行 `{type:'session',...}` 单独提取；打包块行（text-chunks / reasoning-chunks /\n * tool-call-chunks 等无 `seq` 的裸标签行）与未知行跳过，不作为事件。\n */\nexport function parseLog(text) {\n  let header = undefined\n  const events = []\n  let parseErrors = 0\n  for (const rawLine of String(text).split(/\\r?\\n/)) {\n    const line = rawLine.trim()\n    if (line === '') continue\n    let rec\n    try {\n      rec = JSON.parse(line)\n    } catch {\n      parseErrors += 1\n      continue\n    }\n    if (rec === null || typeof rec !== 'object') {\n      parseErrors += 1\n      continue\n    }\n    if (rec.type === 'session') {\n      header = rec\n      continue\n    }\n    if (typeof rec.type === 'string' && typeof rec.seq === 'number') {\n      events.push(rec)\n    }\n  }\n  return { header, events, parseErrors }\n}\n\n/** 从事件里抽取用户消息文本块（content[].text）。 */\nexport function userTextsOf(event) {\n  const data = event.data\n  const content = data?.content\n  if (!Array.isArray(content)) return []\n  return content\n    .filter((block) => block && typeof block === 'object' && block.type === 'text' && typeof block.text === 'string')\n    .map((block) => block.text)\n}\n\n/** 从 tool/call 事件的 arguments（JSON 字符串）抽取结构化参数。 */\nexport function toolArgsOf(event) {\n  const data = event.data\n  const argsText = data?.arguments\n  if (typeof argsText !== 'string' || argsText.trim() === '') return {}\n  try {\n    const parsed = JSON.parse(argsText)\n    return parsed && typeof parsed === 'object' ? parsed : {}\n  } catch {\n    return {}\n  }\n}\n\n/** 从 tool/call 参数中抽取文件路径线索（file_path / path / file / command 内的路径）。 */\nexport function fileCluesOf(toolName, args) {\n  const clues = []\n  const push = (value) => {\n    if (typeof value !== 'string' || value.trim() === '') return\n    const path = value.trim()\n    if (path.includes('..') || path.startsWith('/dev/') || path.startsWith('/proc/')) return\n    if (FILE_TOOL_NAMES.has(toolName) || path.startsWith('/') || path.startsWith('~')) {\n      clues.push(path)\n    }\n  }\n  push(args.file_path)\n  push(args.path)\n  push(args.file)\n  if (toolName === 'bash' && typeof args.command === 'string') {\n    // 只收集明确的文件操作线索，避免把任意命令输出当文件。\n    for (const match of args.command.matchAll(/(?:^|\\s)((?:\\.{0,2}\\/)?[\\w@./-]+\\.[\\w]{1,12})(?:\\s|$)/g)) {\n      const path = match[1]\n      if (/^(git|npm|pnpm|yarn|node|tsx|dsh|cd|ls|echo|cat)/.test(path)) continue\n      clues.push(path)\n    }\n  }\n  return [...new Set(clues)]\n}\n\n/** 视为「文件改动」的工具名集合（增强文件改动线索的可信度）。 */\nexport const FILE_TOOL_NAMES = new Set([\n  'write', 'edit', 'create', 'rename', 'delete', 'move', 'mkdir', 'patch', 'apply_patch',\n  'writeFile', 'editFile', 'createFile', 'rm', 'mv', 'cp', 'touch',\n])\n\n/**\n * 构建单个会话的统一摘要（纯数据，无引用）。\n */\nexport function buildSessionSummary({ path, header, events, parseErrors = 0 }) {\n  const withTime = events\n    .map((event) => ({ event, time: toMs(event.time) }))\n    .filter((entry) => entry.time !== undefined)\n    .sort((a, b) => a.time - b.time)\n\n  const firstTime = withTime.length > 0 ? withTime[0].time : undefined\n  const lastTime = withTime.length > 0 ? withTime[withTime.length - 1].time : undefined\n\n  const titleEvent = events.find((event) => event.type === 'session/title')\n  const title = typeof titleEvent?.data?.title === 'string' ? titleEvent.data.title : undefined\n\n  const userMessages = withTime\n    .filter((entry) => entry.event.type === 'user/message')\n    .map((entry) => ({ text: userTextsOf(entry.event).join('\\n'), time: entry.time }))\n    .filter((entry) => entry.text !== '')\n\n  const prompts = userMessages.map((entry) => entry.text)\n\n  const toolCalls = withTime\n    .filter((entry) => entry.event.type === 'tool/call')\n    .map((entry) => ({\n      name: String(entry.event.data?.name ?? 'unknown'),\n      args: toolArgsOf(entry.event),\n      time: entry.time,\n    }))\n\n  const toolFreq = new Map()\n  const files = new Map()\n  for (const call of toolCalls) {\n    toolFreq.set(call.name, (toolFreq.get(call.name) ?? 0) + 1)\n    for (const path of fileCluesOf(call.name, call.args)) {\n      const record = files.get(path) ?? { path, tools: new Set(), count: 0 }\n      record.tools.add(call.name)\n      record.count += 1\n      files.set(path, record)\n    }\n  }\n\n  const dayKeys = new Set(withTime.map((entry) => isoDay(entry.time)))\n\n  const counts = {\n    toolCalls: toolCalls.length,\n    toolResults: events.filter((event) => event.type === 'tool/result').length,\n    userMessages: userMessages.length,\n    assistantMessages: events.filter((event) => event.type === 'assistant/message').length,\n    steps: events.filter((event) => event.type === 'step/start').length,\n    turns: events.filter((event) => event.type === 'turn/start').length,\n    approvals: events.filter((event) => event.type === 'approval/asked').length,\n    retries: events.filter((event) => event.type === 'llm/retry').length,\n  }\n\n  return {\n    path,\n    id: typeof header?.id === 'string' ? header.id : undefined,\n    cwd: typeof header?.cwd === 'string' && header.cwd !== '' ? header.cwd : undefined,\n    agentPreset: typeof header?.agentPreset === 'string' ? header.agentPreset : undefined,\n    createdAt: typeof header?.createdAt === 'number' ? header.createdAt : firstTime,\n    title,\n    firstTime,\n    lastTime,\n    durationMs: firstTime !== undefined && lastTime !== undefined ? Math.max(0, lastTime - firstTime) : 0,\n    dayKeys: [...dayKeys].sort(),\n    prompts,\n    counts,\n    toolFreq: [...toolFreq.entries()].map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count),\n    files: [...files.values()]\n      .map((record) => ({ path: record.path, tools: [...record.tools], count: record.count }))\n      .sort((a, b) => b.count - a.count),\n    parseErrors,\n  }\n}\n\n/** epoch ms → 'YYYY-MM-DD'（UTC，稳定可测）。 */\nexport function isoDay(ms) {\n  return new Date(ms).toISOString().slice(0, 10)\n}\n\n/** 毫秒 → 人类可读耗时。 */\nexport function formatDuration(ms) {\n  if (ms < MINUTE_MS) return `${Math.max(0, Math.round(ms / 1000))}s`\n  if (ms < HOUR_MS) return `${Math.round(ms / MINUTE_MS)}m`\n  const hours = Math.floor(ms / HOUR_MS)\n  const minutes = Math.round((ms % HOUR_MS) / MINUTE_MS)\n  return minutes > 0 ? `${hours}h ${minutes}m` : `${hours}h`\n}\n\n// ---------------------------------------------------------------------------\n// 主题分类与聚合\n// ---------------------------------------------------------------------------\n\n/** 主题关键词分类（确定性；对 prompt 标题做子串匹配）。 */\nexport const TOPIC_KEYWORDS = Object.freeze([\n  { topic: 'bug修复/调试', keywords: ['bug', '修复', 'debug', '报错', '崩溃', '异常', '排查', '错误', '故障'] },\n  { topic: '功能开发/设计', keywords: ['功能', '开发', '实现', '新增', '接口', '设计', 'feature', 'implement', 'add', '开发'] },\n  { topic: '重构/优化', keywords: ['重构', '优化', 'refactor', '清理', '简化', 'perf', '性能', '重构'] },\n  { topic: '测试', keywords: ['测试', 'test', 'spec', '单测', '冒烟'] },\n  { topic: '文档/说明', keywords: ['文档', 'readme', 'doc', '说明', '注释', '文档'] },\n  { topic: '依赖/构建', keywords: ['依赖', 'dependency', '构建', 'build', '安装', 'install', 'package', 'npm', '依赖'] },\n  { topic: '部署/发布', keywords: ['部署', 'deploy', '发布', 'release', '上线'] },\n  { topic: '检视/审查', keywords: ['review', '审查', '检视', '检查', 'pr'] },\n])\n\n/**\n * 对若干段文本做主题归类，返回 `[{ topic, sessions }]`（按命中的会话数降序）。\n */\nexport function classifyTopics(texts) {\n  const joined = texts.join('\\n').toLowerCase()\n  const hits = TOPIC_KEYWORDS\n    .map(({ topic, keywords }) => ({ topic, count: keywords.filter((k) => joined.includes(k.toLowerCase())).length }))\n    .filter((entry) => entry.count > 0)\n    .sort((a, b) => b.count - a.count)\n  return hits.map(({ topic }) => ({ topic }))\n}\n\n/** 会话是否与时间窗 [since, until] 有活动重叠。 */\nexport function sessionInWindow(session, since, until) {\n  if (session.firstTime === undefined) return session.createdAt !== undefined && session.createdAt >= since && session.createdAt <= until\n  return session.lastTime >= since && session.firstTime <= until\n}\n\n/** 会话是否命中 repo 子串过滤（对 cwd 与路径不区分大小写）。 */\nexport function sessionMatchesRepo(session, repo) {\n  if (!repo) return true\n  const needle = String(repo).toLowerCase()\n  const haystack = [session.cwd ?? '', session.path ?? ''].join('\\n').toLowerCase()\n  return haystack.includes(needle)\n}\n\n/**\n * 聚合多会话摘要 → 顶层摘要对象（含 git 交叉验证占位）。\n */\nexport function aggregateSummaries(sessions, opts = {}) {\n  const { repo, since, until, now = Date.now(), git = true, gitBin = 'git' } = opts\n\n  const inWindow = sessions.filter((session) => sessionInWindow(session, since, until))\n  const filtered = inWindow.filter((session) => sessionMatchesRepo(session, repo))\n\n  const sessionsOut = filtered.map((session) => ({\n    id: session.id ?? basename(dirname(session.path)),\n    cwd: session.cwd,\n    title: session.title,\n    agentPreset: session.agentPreset,\n    createdAt: session.createdAt,\n    firstTime: session.firstTime,\n    lastTime: session.lastTime,\n    durationMs: session.durationMs,\n    userMessages: session.counts.userMessages,\n    toolCalls: session.counts.toolCalls,\n    topTools: session.toolFreq.slice(0, 5),\n    files: session.files.slice(0, 12),\n    dayKeys: session.dayKeys,\n    parseErrors: session.parseErrors,\n  }))\n\n  const toolFreq = new Map()\n  const perDay = new Map()\n  for (const session of filtered) {\n    for (const { name, count } of session.toolFreq) toolFreq.set(name, (toolFreq.get(name) ?? 0) + count)\n    for (const day of session.dayKeys) {\n      const record = perDay.get(day) ?? { day, sessions: new Set(), toolCalls: 0 }\n      record.sessions.add(session.id ?? session.path)\n      record.toolCalls += session.counts.toolCalls / Math.max(1, session.dayKeys.length)\n      perDay.set(day, record)\n    }\n  }\n\n  const projects = new Map()\n  for (const session of filtered) {\n    const key = session.cwd ?? '(未知目录)'\n    const record = projects.get(key) ?? {\n      cwd: session.cwd,\n      sessions: new Set(),\n      toolCalls: 0,\n      firstTime: undefined,\n      lastTime: undefined,\n    }\n    record.sessions.add(session.id ?? session.path)\n    record.toolCalls += session.counts.toolCalls\n    if (record.firstTime === undefined || (session.firstTime ?? Infinity) < record.firstTime) record.firstTime = session.firstTime\n    if (record.lastTime === undefined || (session.lastTime ?? -Infinity) > record.lastTime) record.lastTime = session.lastTime\n    projects.set(key, record)\n  }\n\n  const fileChanges = new Map()\n  for (const session of filtered) {\n    for (const { path, tools, count } of session.files) {\n      const record = fileChanges.get(path) ?? { path, tools: new Set(), count: 0 }\n      for (const tool of tools) record.tools.add(tool)\n      record.count += count\n      fileChanges.set(path, record)\n    }\n  }\n\n  const promptPool = []\n  for (const session of filtered) {\n    promptPool.push(session.title ?? '')\n    promptPool.push(...session.prompts)\n  }\n\n  const totals = {\n    sessions: sessionsOut.length,\n    projects: projects.size,\n    toolCalls: filtered.reduce((sum, session) => sum + session.counts.toolCalls, 0),\n    toolResults: filtered.reduce((sum, session) => sum + session.counts.toolResults, 0),\n    userMessages: filtered.reduce((sum, session) => sum + session.counts.userMessages, 0),\n    approvals: filtered.reduce((sum, session) => sum + session.counts.approvals, 0),\n    durationMs: filtered.reduce((sum, session) => sum + session.durationMs, 0),\n    distinctDays: new Set(filtered.flatMap((session) => session.dayKeys)).size,\n    parseErrors: filtered.reduce((sum, session) => sum + session.parseErrors, 0),\n  }\n  const allTimes = filtered.flatMap((session) => [session.firstTime, session.lastTime]).filter((t) => t !== undefined)\n  totals.firstActivity = allTimes.length > 0 ? Math.min(...allTimes) : undefined\n  totals.lastActivity = allTimes.length > 0 ? Math.max(...allTimes) : undefined\n\n  const summary = {\n    generatedAt: now,\n    period: { key: opts.periodKey ?? 'month', days: Math.round((until - since) / DAY_MS), since, until },\n    sourceRoot: opts.sourceRoot,\n    compression: opts.compression ?? 'unknown',\n    redacted: false,\n    totals,\n    topics: classifyTopics(promptPool),\n    toolFreq: [...toolFreq.entries()].map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count),\n    perDay: [...perDay.values()]\n      .map(({ day, sessions, toolCalls }) => ({ day, sessions: sessions.size, toolCalls: Math.round(toolCalls) }))\n      .sort((a, b) => a.day.localeCompare(b.day)),\n    projects: [...projects.values()].map((record) => ({\n      cwd: record.cwd,\n      sessions: record.sessions.size,\n      toolCalls: record.toolCalls,\n      firstTime: record.firstTime,\n      lastTime: record.lastTime,\n      gitStatus: 'pending',\n      gitCommits: null,\n      gitReason: undefined,\n    })),\n    fileChanges: [...fileChanges.values()]\n      .map((record) => ({ path: record.path, tools: [...record.tools], count: record.count }))\n      .sort((a, b) => b.count - a.count),\n    sessions: sessionsOut,\n    truncated: false,\n  }\n\n  // git 交叉验证是异步 I/O，由 mineSessions 用 attachGitCrossCheck 补齐；\n  // 此处（纯聚合）统一标记 pending，由调用方决定。\n  summary.projects = summary.projects.map((project) => ({ ...project, gitStatus: git ? 'pending' : 'unavailable', gitReason: git ? undefined : 'git 交叉验证被禁用' }))\n  return summary\n}\n\n// ---------- 聚合阶段真正的异步 git 交叉验证（与 aggregateSummaries 分离） ----------\n\n/**\n * 异步版 git 交叉验证：对 summary.projects 就地补全 gitStatus/gitCommits。\n * 需要真实文件系统。\n * @param {object} summary - 摘要对象（含 projects 数组）。\n * @param {object} [opts] - 选项。\n * @param {number} [opts.since] - 时间窗起点（epoch ms）。\n * @param {number} [opts.until] - 时间窗终点（epoch ms）。\n * @param {string} [opts.gitBin] - git 可执行文件（默认 git）。\n * @param {boolean} [opts.enabled] - 是否启用（默认 true；false 时统一标 unavailable）。\n * @returns {Promise<object>} 补全后的摘要对象。\n */\nexport async function attachGitCrossCheck(summary, opts = {}) {\n  const { since = 0, until = Date.now(), gitBin = 'git', enabled = true } = opts\n  if (!enabled) {\n    su