      "content": "#!/usr/bin/env node\n/**\n * dsh-receipts — scripts/report.mjs\n *\n * 摘要 JSON → Markdown 报告 + 自包含 HTML receipt（模板内嵌，无任何外链）。\n * 纯模板渲染，零网络、零模型调用（上游唯一一次 LLM 调用在本实现中被模板化替代，\n * 成本更低；需要叙事润色时由 agent 在后续步骤用 receipts 摘要做一次模型调用即可）。\n *\n * 网络白名单（验收标准 4）：本文件不 import 任何网络模块，不调用 fetch；\n * assets/template.html 内同样不含任何外部资源 URL。\n *\n * 用法（CLI）：\n *   node scripts/report.mjs --summary <摘要.json> --out-dir <输出目录> [--base-name receipts-2026-08-20] [--md-only]\n *\n * 库用法（测试直接导入）：\n *   import { buildReport, renderMarkdown, renderHtml } from '../scripts/report.mjs'\n */\n\nimport { readFileSync } from 'node:fs'\nimport { promises as fsp } from 'node:fs'\nimport { dirname, join } from 'node:path'\nimport { fileURLToPath, pathToFileURL } from 'node:url'\n\nconst thisDir = dirname(fileURLToPath(import.meta.url))\n\n/** Markdown 表格转义（管道符等）。 */\nexport function mdCell(value) {\n  return String(value ?? '').replaceAll('|', '\\\\|').replaceAll('\\n', ' ')\n}\n\n/** Markdown 表头行。 */\nexport function mdTable(headers, rows) {\n  const header = `| ${headers.join(' | ')} |`\n  const divider = `| ${headers.map(() => '---').join(' | ')} |`\n  const body = rows.map((row) => `| ${row.map(mdCell).join(' | ')} |`)\n  return [header, divider, ...body].join('\\n')\n}\n\n/**\n * 本地时区钟面时间（epoch ms → `YYYY-MM-DD HH:MM:SS (GMT±HHMM)`）。\n * 这是模板与 CLI 的**唯一实现**：renderHtml 会把本函数源码注入静态模板的\n * `__RECEIPTS_FMTTIME__` 占位符，保证 HTML 内不再有一份容易漂移的克隆。\n */\nexport function fmtTime(ms) {\n  if (ms === undefined || ms === null || !Number.isFinite(ms)) return '—'\n  const d = new Date(ms)\n  const pad = (n) => String(n).padStart(2, '0')\n  const off = -d.getTimezoneOffset()\n  const sign = off >= 0 ? '+' : '-'\n  const abs = Math.abs(off)\n  const tz = `GMT${sign}${pad(Math.floor(abs / 60))}${pad(abs % 60)}`\n  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} `\n    + `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())} (${tz})`\n}\n\n/** 毫秒 → 人类可读耗时。 */\nexport function fmtDuration(ms) {\n  if (!Number.isFinite(ms)) return '—'\n  const totalSeconds = Math.max(0, Math.round(ms / 1000))\n  if (totalSeconds < 60) return `${totalSeconds}s`\n  const minutes = Math.floor(totalSeconds / 60)\n  if (minutes < 60) return `${minutes}m ${totalSeconds % 60}s`\n  const hours = Math.floor(minutes / 60)\n  return `${hours}h ${minutes % 60}m`\n}\n\n/** 项目 git 状态的可读描述。 */\nexport function gitStatusLine(project) {\n  if (project.gitStatus === 'verified') return `✓ ${project.gitCommits} 个 commit（git log 交叉验证）`\n  return `无法交叉验证（${project.gitReason ?? '未知原因'}）`\n}\n\n/** 从摘要对象渲染 Markdown 报告正文。 */\nexport function renderMarkdown(summary) {\n  const { totals, period } = summary\n  const now = summary.generatedAt ?? Date.now()\n  const lines = []\n  lines.push(`# DSH 使用与影响报告（Receipt）`)\n  lines.push('')\n  lines.push(`> 生成时间：${fmtTime(now)} ｜ 报告周期：${period.days} 天（${fmtTime(period.since)} ~ ${fmtTime(period.until)}）`)\n  lines.push('')\n\n  // 解码失败的日志进入 skipped：明确展示，避免「假空」报告被当作真实数据使用。\n  if (Array.isArray(summary.skipped) && summary.skipped.length > 0) {\n    lines.push(`> ⚠️ 有 ${summary.skipped.length} 个会话日志无法解码而被跳过（相关会话不计入本报告）。`)\n    for (const item of summary.skipped) {\n      lines.push(`> - ${item.path}：${item.reason}`)\n    }\n    lines.push('')\n  }\n\n  lines.push('## 概览')\n  lines.push('')\n  lines.push(mdTable(\n    ['指标', '数值'],\n    [\n      ['会话数', totals.sessions],\n      ['涉及项目数', totals.projects],\n      ['工具调用总数', totals.toolCalls],\n      ['工具结果数', totals.toolResults],\n      ['用户消息数', totals.userMessages],\n      ['审批请求数', totals.approvals],\n      ['累计活动时长', fmtDuration(totals.durationMs)],\n      ['活动跨天数', totals.distinctDays],\n      ['跳过文件数', totals.skippedSessions],\n      ['首条活动', fmtTime(totals.firstActivity, now)],\n      ['末条活动', fmtTime(totals.lastActivity, now)],\n    ],\n  ))\n  lines.push('')\n\n  if (summary.topics.length > 0) {\n    lines.push('## 主题分类')\n    lines.push('')\n    lines.push(mdTable(['主题', '命中'], summary.topics.map((topic) => [topic.topic, '—'])))\n    lines.push('')\n  }\n\n  if (summary.toolFreq.length > 0) {\n    lines.push('## 工具调用频次 Top N')\n    lines.push('')\n    lines.push(mdTable(['工具', '调用次数'], summary.toolFreq.map((entry) => [entry.name, entry.count])))\n    lines.push('')\n  }\n\n  if (summary.perDay.length > 0) {\n    lines.push('## 按天分布')\n    lines.push('')\n    lines.push(mdTable(['日期', '会话数', '工具调用数'], summary.perDay.map((entry) => [entry.day, entry.sessions, entry.toolCalls])))\n    lines.push('')\n  }\n\n  lines.push('## 项目 × 会话')\n  lines.push('')\n  lines.push(mdTable(\n    ['项目目录', '会话数', '工具调用数', 'git 交叉'],\n    summary.projects.map((project) => [project.cwd ?? '(未知)', project.sessions, project.toolCalls, gitStatusLine(project)]),\n  ))\n  lines.push('')\n\n  if (summary.fileChanges.length > 0) {\n    lines.push('## 文件改动线索 Top N')\n    lines.push('')\n    lines.push(mdTable(\n      ['文件', '涉及工具', '出现次数'],\n      summary.fileChanges.map((entry) => [entry.path, entry.tools.join(', '), entry.count]),\n    ))\n    lines.push('')\n  }\n\n  lines.push('## 会话明细')\n  lines.push('')\n  if (summary.sessions.length === 0) {\n    lines.push('（周期内无命中会话）')\n    lines.push('')\n  }\n  for (const session of summary.sessions) {\n    lines.push(`### ${session.title ?? '（无标题）'}`)\n    lines.push('')\n    lines.push(mdTable(\n      ['字段', '值'],\n      [\n        ['会话 ID', session.id ?? '—'],\n        ['项目目录', session.cwd ?? '（未知）'],\n        ['创建时间', fmtTime(session.createdAt, now)],\n        ['活动区间', `${fmtTime(session.firstTime, now)} ~ ${fmtTime(session.lastTime, now)}`],\n        ['活动时长', fmtDuration(session.durationMs)],\n        ['用户消息', session.userMessages],\n        ['工具调用', session.toolCalls],\n        ['Top 工具', session.topTools.map((tool) => `${tool.name}(${tool.count})`).join(', ') || '—'],\n      ],\n    ))\n    lines.push('')\n    if (session.files.length > 0) {\n      lines.push('改动文件线索：')\n      lines.push('')\n      lines.push(mdTable(\n        ['文件', '涉及工具', '次数'],\n        session.files.map((file) => [file.path, file.tools.join(', '), file.count]),\n      ))\n      lines.push('')\n    }\n  }\n\n  if (summary.truncated) {\n    lines.push('> 注意：摘要超过 20KB 上限，明细已被截断（仅影响报告详略，不影响核心统计）。')\n    lines.push('')\n  }\n\n  lines.push('---')\n  lines.push('')\n  lines.push('## 附注')\n  lines.push('')\n  lines.push('- 数据源：' + (summary.sourceRoot ?? '（未记录）') + '（只读本地 DSH 会话日志，绝不外发）')\n  lines.push('- 压缩模式：' + (summary.compression === 'none' ? `none（明文 JSONL）` : summary.compression === 'zstd' ? 'zstd（自动解压）' : '未知'))\n  lines.push('- 脱敏：' + (summary.redacted ? '已开启（绝对路径折叠为 <redacted>/<basename>）' : '未开启'))\n  lines.push('- 挖掘阶段零网络、零模型调用；git 交叉验证仅访问本地仓库。')\n  lines.push('')\n  return lines.join('\\n')\n}\n\n/** 从摘要对象渲染完整 HTML 文档字符串。 */\nexport function renderHtml(summary, opts = {}) {\n  const template = opts.template ?? loadTemplate()\n  const title = opts.title ?? 'DSH 使用与影响报告'\n  // 内嵌 JSON 安全转义：把 `<` 写成 \\u003c，杜绝闭合 </script> 形成持久 XSS；\n  // \\u003c 是合法 JSON 转义，JSON.parse 后会还原为 `<`，数据不丢失。\n  const dataJson = JSON.stringify(summary).replace(/</g, '\\\\u003c')\n  return template\n    .replaceAll('{{TITLE}}', escapeHtml(title))\n    .replaceAll('__RECEIPTS_SUMMARY__', () => dataJson)\n    // 单一时间实现：把 report.mjs 的 fmtTime 源码注入模板，模板不再自带克隆。\n    .replaceAll('__RECEIPTS_FMTTIME__', () => `(${fmtTime.toString()})`)\n}\n\n/** HTML 实体转义。 */\nexport function escapeHtml(value) {\n  return String(value)\n    .replaceAll('&', '&amp;')\n    .replaceAll('<', '&lt;')\n    .replaceAll('>', '&gt;')\n    .replaceAll('\"', '&quot;')\n    .replaceAll(\"'\", '&#39;')\n}\n\n/** 读取 assets/template.html（相对本脚本；同步读取，供同步渲染调用）。 */\nexport function loadTemplate() {\n  const templatePath = join(thisDir, '..', 'assets', 'template.html')\n  return readFileSync(templatePath, 'utf8')\n}\n\n/** 内建默认模板（当 assets/template.html 缺失时的兜底，仍完全自包含）。 */\nexport function fallbackTemplate() {\n  return `<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<title>{{TITLE}}</title>\n<style>\nbody{font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;max-width:900px;margin:2rem auto;padding:0 1rem;color:#1f2328;line-height:1.6}\nh1{font-size:1.6rem}h2{font-size:1.2rem;border-bottom:1px solid #d0d7de;padding-bottom:.3rem;margin-top:2rem}\ntable{border-collapse:collapse;width:100%;margin:1rem 0;font-size:.9rem}\nth,td{border:1px solid #d0d7de;padding:.4rem .6rem;text-align:left}th{background:#f6f8fa}\ncode{background:#f6f8fa;padding:.1rem .3rem;border-radius:4px}\n.alert{background:#fff8c5;border:1px solid #d4a72c;padding:.6rem .8rem;border-radius:6px}\nfooter{margin-top:3rem;color:#57606a;font-size:.85rem;border-top:1px solid #d0d7de;padding-top:1rem}\n</style>\n</head>\n<body>\n<h1>{{TITLE}}</h1>\n<script id=\"receipts-data\" type=\"application/json\">__RECEIPTS_SUMMARY__</script>\n<script>document.getElementById('receipts-data').textContent</script>\n<footer>本报告由 dsh-receipts 本地生成，无外部资源。</footer>\n</body>\n</html>`\n}\n\n/** 默认输出文件主名：`receipts-<YYYY-MM-DD>`（最近活动日/生成日的 UTC 日期）。 */\nexport function defaultBaseName(summary) {\n  const stamp = summary.lastActivity ?? summary.generatedAt ?? Date.now()\n  return `receipts-${new Date(stamp).toISOString().slice(0, 10)}`\n}\n\n/** 把 Markdown 与 HTML 写入 outDir；返回文件路径列表。 */\nexport async function writeReports(markdown, html, outDir, baseName) {\n  await fsp.mkdir(outDir, { recursive: true })\n  const markdownPath = join(outDir, `${baseName}.md`)\n  const htmlPath = join(outDir, `${baseName}.html`)\n  await fsp.writeFile(markdownPath, markdown, 'utf8')\n  await fsp.writeFile(htmlPath, html, 'utf8')\n  return [markdownPath, htmlPath]\n}\n\n/** 摘要 → 报告（内存）。 */\nexport async function buildReport(summary, opts = {}) {\n  const markdown = renderMarkdown(summary)\n  const html = renderHtml(summary, opts)\n  return { markdown, html }\n}\n\n/** CLI 入口函数（测试可调用）。 */\nexport async function runCli(argv) {\n  const args = {}\n  try {\n    for (let i = 0; i < argv.length; i += 1) {\n      const token = argv[i]\n      const read = (name) => {\n        const value = argv[i + 1]\n        if (value === undefined) throw new Error(`缺少参数值: ${name}`)\n        i += 1\n        return value\n      }\n      switch (token) {\n        case '--summary': args.summaryPath = read(token); break\n        case '--out-dir': args.outDir = read(token); break\n        case '--base-name': args.baseName = read(token); break\n        case '--md-only': args.mdOnly = true; break\n        case '--help':\n        case '-h': args.help = true; break\n        default: throw new Error(`未知参数: ${token}`)\n      }\n    }\n  } catch (error) {\n    return { exitCode: 2, stdout: '', stderr: `${error.message}\\n用法: node scripts/report.mjs --summary <摘要.json> --out-dir <目录> [--base-name <名>] [--md-only]` }\n  }\n  if (args.help) return { exitCode: 0, stdout: '用法: node scripts/report.mjs --summary <摘要.json> --out-dir <目录> [--base-name <名>] [--md-only]', stderr: '' }\n  try {\n    const summary = JSON.parse(await fsp.readFile(args.summaryPath, 'utf8'))\n    const { markdown, html } = await buildReport(summary, { title: 'DSH 使用与影响报告' })\n    const baseName = args.baseName ?? defaultBaseName(summary)\n    if (args.mdOnly) {\n      return { exitCode: 0, stdout: markdown, stderr: '' }\n    }\n    const paths = await writeReports(markdown, html, args.outDir, baseName)\n    return { exitCode: 0, stdout: paths.join('\\n'), stderr: '' }\n  } catch (error) {\n    return { exitCode: 1, stdout: '', stderr: `report 生成失败: ${error.message}` }\n  }\n}\n\n/** 直接以脚本方式运行时执行 CLI。 */\nconst thisUrl = import.meta.url\nconst isMain = process.argv[1] !== undefined && thisUrl === pathToFileURL(process.argv[1]).href\nif (isMain) {\n  const result = await runCli(process.argv.slice(2))\n  process.stdout.write(result.stdout)\n  process.stderr.write(result.stderr)\n  process.exitCode = result.exitCode\n}"
    }
